ALTER TABLE conversations ADD COLUMN stage text NOT NULL DEFAULT 'TRIAGE' CHECK(stage IN('TRIAGE','CLARIFYING','PROPOSAL','ACCEPTED','HUMAN','COMPLETED'));
ALTER TABLE appointments ADD COLUMN conversation_id uuid,ADD FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id);
CREATE TABLE conversation_proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,conversation_id uuid NOT NULL,patient_id uuid,appointments jsonb NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','ACCEPTED','APPROVED','REJECTED')),reason text NOT NULL DEFAULT '',request_id uuid NOT NULL,agent_run_id uuid,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),decided_by uuid REFERENCES users(id),decided_at timestamptz,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),FOREIGN KEY(tenant_id,agent_run_id) REFERENCES agent_runs(tenant_id,id),UNIQUE(tenant_id,conversation_id,request_id),UNIQUE(tenant_id,agent_run_id),UNIQUE(tenant_id,id));
